-- Generated by `scrapagents generate-dbt` from configs/contracts/caf/convocatorias.yml. Do not edit: change the contract and regenerate.
{{ config(tags=["source_caf"]) }}

with source as (

    select * from {{ source('caf', 'convocatorias') }}

),

records as (

    select
        payload as record,
        _batch_id::text as bronze_batch_id,
        _record_hash as bronze_record_hash,
        _landing_uri as bronze_landing_uri,
        _ingested_at as bronze_ingested_at
    from source

)

select
    (record ->> 'process_id')::text as process_id,
    (record ->> 'title')::text as title,
    (record ->> 'status')::text as status,
    (record ->> 'country')::text as country,
    (record ->> 'category')::text as category,
    (record ->> 'publication_date')::date as publication_date,
    (record ->> 'closing_date')::date as closing_date,
    (record ->> 'source_url')::text as source_url,
    (record ->> 'tdr_document_url')::text as tdr_document_url,
    (record ->> 'contact_email')::text as contact_email,
    bronze_batch_id,
    bronze_record_hash,
    bronze_landing_uri,
    bronze_ingested_at
from records
